assignment = [3, 0, 3, 1, 1, 0, 2, 0, 0, 3, 2, 1, 3, 4, 0, 3, 3, 1, 2, 0, 1, 4, 2, 4]
# i-th entry (0-indexed) gives subset assignment of integer i+1

subsets = {0: [], 1: [], 2: [], 3: [], 4: []}
for i, subset in enumerate(assignment):
    subsets[subset].append(i+1)

for s, nums in sorted(subsets.items()):
    print(f"Subset {s}: {nums}, sum={sum(nums)}")
